import { parseArgs } from 'node:util';
import { readFile, writeFile, mkdir, stat } from 'node:fs/promises';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { build } from 'esbuild';

const { values } = parseArgs({ options: { model: { type: 'string' }, name: { type: 'string', default: 'VYLNT experimental baseline' }, check: { type: 'boolean', default: false } } });
if (!values.model || !values.name.trim() || values.name.length > 80) throw new Error('Use --model <model.json> [--name <release-name>] [--check]');
await mkdir('.local', { recursive: true });
const modulePath = resolve('.local/ml-release-validation.mjs');
await build({ stdin: { contents: "export { parseAnalysisModel } from './packages/core/ml-model'; export { modelFileByteLimit } from './packages/core/ml-inference'; export { RULESET_VERSION } from './packages/core';", resolveDir: process.cwd() }, bundle: true, outfile: modulePath, platform: 'node', format: 'esm', packages: 'external' });
const { parseAnalysisModel, modelFileByteLimit, RULESET_VERSION } = await import(pathToFileURL(modulePath).href);
const input = resolve(values.model), output = resolve('packages/ml/bundled-model.ts');
if ((await stat(input)).size > modelFileByteLimit) throw new Error('Model exceeds 64 KiB.');
const model = parseAnalysisModel(JSON.parse(await readFile(input, 'utf8')));
if (model.rulesetVersion !== RULESET_VERSION) throw new Error('Model must match the current VYLNT ruleset before bundling.');
if (!values.check) {
  await writeFile(output, '// VYLNT-managed experimental release. Generated by npm run ml:bundle.\nexport const bundledModel = ' + JSON.stringify({ name: values.name.trim(), model }, null, 2) + ';\n');
}
console.log(`VYLNT model ${values.check ? 'validated' : 'bundled'} (${model.provenance}, experimental). This does not certify accuracy. ${values.check ? '' : 'Record the release/evaluation in PLAN.md, then rebuild and deploy the dashboard.'}`);
